def inspect_source(module):
    """Helper function to get the source code of a module"""
    if hasattr(module, "__file__"):
        try:
            with open(module.__file__, "r") as f:
                return f.read()
        except:
            pass

    # Fallback using inspect
    try:
        return inspect.getsource(module)
    except:
        return ""

