import pytest
import inspect
import re
import ast
import os

# Helper functions for testing
def get_function_source(module_path, class_name, method_name):
    """Extract the source code of a method from a file"""
    try:
        with open(module_path, 'r') as file:
            source = file.read()

        # Use AST to parse and find the method
        module_ast = ast.parse(source)
        for node in ast.walk(module_ast):
            if isinstance(node, ast.ClassDef) and node.name == class_name:
                for item in node.body:
                    if isinstance(item, ast.FunctionDef) and item.name == method_name:
                        # Get the source lines for this function
                        start_line = item.lineno
                        end_line = item.end_lineno if hasattr(item, 'end_lineno') else None

                        if end_line:
                            method_lines = source.splitlines()[start_line-1:end_line]
                        else:
                            # Extract function with indentation logic
                            method_lines = []
                            lines = source.splitlines()
                            in_function = False
                            indent_level = None

                            for i, line in enumerate(lines):
                                if i+1 == start_line:
                                    in_function = True
                                    method_lines.append(line)
                                    indent_level = len(line) - len(line.lstrip())
                                elif in_function:
                                    current_indent = len(line) - len(line.lstrip())
                                    if line.strip() and current_indent <= indent_level:
                                        break
                                    method_lines.append(line)

                        return '\n'.join(method_lines)
        return None
    except Exception as e:
        return f"Error reading file: {str(e)}"

def has_try_except_inside_loop(source_code):
    """Check if try-except is inside a loop over tickers"""
    if not source_code or isinstance(source_code, str) and source_code.startswith("Error reading file:"):
        return False

    try:
        parsed_ast = ast.parse(source_code)
        for node in ast.walk(parsed_ast):
            if isinstance(node, ast.For):
                for item in ast.walk(node):
                    if isinstance(item, ast.Try):
                        return True
        return False
    except SyntaxError:
        # Fallback for syntax errors
        for_index = source_code.find("for ")
        try_index = source_code.find("try:")
        return (for_index != -1 and try_index != -1 and for_index < try_index)

# Essential tests for try-except error handling
def test_fill_gaps_for_all_tickers_has_try_except(implementation):
    """Test if fill_gaps_for_all_tickers method has try-except block for error handling"""
    impl_name, module = implementation

    module_path = module.__file__
    assert module_path is not None, f"Cannot get module path for {impl_name}"

    method_source = get_function_source(module_path, 'Datafeed', 'fill_gaps_for_all_tickers')
    assert method_source is not None and not method_source.startswith("Error reading file:"), f"Could not extract method source code for {impl_name}: {method_source}"

    has_try_except = "try:" in method_source and "except" in method_source
    assert has_try_except, f"Implementation {impl_name} does not have try-except block in fill_gaps_for_all_tickers"

